import re,os,subprocess
hdrs=[]
for root,dirs,files in os.walk('server/include'):
    for f in files:
        if f.endswith(('.h','.hpp')): hdrs.append(os.path.join(root,f))
decl=re.compile(r'^\s{4}(?:[A-Za-z_][\w:<>,*&\s]*?)\b([A-Za-z_]\w*)\s*\([^;]*\)\s*(?:const)?\s*(?:override)?\s*;\s*$')
out={}
for h in hdrs:
    for i,line in enumerate(open(h,encoding='utf-8',errors='replace'),1):
        m=decl.match(line)
        if m:
            name=m.group(1)
            if name in ('if','for','while','switch','return','delete','new'): continue
            out.setdefault(name,[]).append((h,i,line.strip()[:90]))
print(len(out))
import json
json.dump(out,open('/tmp/decl.json','w'))
EOF
