res=[]
for name,locs in out.items():
    if name in generic: continue
    # count occurrences outside test/build/LMA
    p=subprocess.run(['rg','-n','--no-heading','-w',name,'server/src','client','tools','scripts','server/include','-g','!*/test/*'],capture_output=True,text=True)
    lines=[l for l in p.stdout.splitlines() if l.strip()]
    declfiles={h for h,_,_ in locs}
    nondecl=[l for l in lines if not any(l.startswith(h+':') for h in declfiles)]
    if len(nondecl)<=1:
        res.append((name,locs,len(nondecl),nondecl[:3]))
for r in sorted(res,key=lambda x:len(x[3])):
    print(r[0], '| decl:', [f"{h}:{i}" for h,i,_ in r[1]], '| outside:', r[2])
    for l in r[3]: print('    ',l)
