struct WeakNetConfig {
    /**
     * @brief eBPF Map 容量定标配置（config.yaml 扁平键 map_sizing_*）
     *
     * 三个键必须平铺而非嵌套：YAML 解析器只支持两层缩进。
     * 变更需 RestartMonitor 生效（不进 TRIAL 白名单，因为 map 已加载后无法 resize）。
     */
    struct MapSizingCfg {
        ConfigString mode{"auto"};                  ///< auto | fixed
        std::atomic<uint32_t> entries{0};           ///< fixed 生效；auto 下不参与计算
        std::atomic<uint32_t> ram_budget_bp{50};    ///< auto：物理内存的万分之几（50 = 0.5%）
    };

    // ---------- 服务端 ----------
    ConfigString data_dir{""};        ///< 空 → 走 WEAKNET_DATA_DIR / 内置默认
    ConfigString log_level{"info"};

    /**
     * @brief 配置代：任何一次成功的配置写入都会递增。
     *
     * 用途：已发布的 AssessmentSnapshot 带发布时的代次；代次不符即表示
     * 该快照基于旧配置，消费者必须按「过期」处理，不得继续返回旧结论。
     *
     * 由 setMonitorParam() 在写入成功后统一推进，因此本地 D-Bus 调参、
     * 云端下发与事务回滚三条路径都被覆盖，无需各调用点自己记账。
     */
    std::atomic<uint32_t> config_generation{1};

    // ---------- 传统监控线程 ----------
    struct {
        std::atomic<bool> enabled{true};
        ConfigString target{"223.5.5.5"};
        std::atomic<uint32_t> interval_ms{10000};
        std::atomic<uint32_t> timeout_ms{800};
        /// RTT 样本滑动窗口大小（样本数），用于在 rtt 监控线程内计算 Jitter。
        /// <=0 表示不启用抖动统计；原独立 jitter_monitor 已合并进 rtt_monitor。
        std::atomic<uint32_t> window_size{30};
    } rtt;

    // 抖动（Jitter）不再是独立监控项：作为 RTT 的衍生指标，
    // 由 rtt_monitor 在同一次 ping 采样上直接计算滑动窗口标准差。

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{10000};
    } rssi;

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{10000};
    } tcp_loss;

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{10000};
    } traffic;

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{15000};
    } quality;

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{3000};
        ConfigString bpf_obj{"build/a2dp_media.bpf.o"};   ///< Phase2 eBPF 融合层对象（legacy A2DP）
        /// 旧 A2DP 音频探针开关：工业蓝牙 HCI ACL 新探针（bt_hci_traffic）验收通过后
        /// 默认停用，避免两套采集链同时挂在内核上重复统计/增加开销；保留配置键、
        /// bt_history 表与 GetBluetoothAudioQuality 接口兼容，需要时可显式开回。
        std::atomic<bool> a2dp_fusion_enabled{false};
        MapSizingCfg map_sizing;                          ///< a2dp LRU map 定标
        /// Phase 1 设备事件采集器对象（bt_events.bpf.o）。
        /// 与 a2dp_media 是**两条独立的数据路径**：a2dp 走 map 累计音频流量，
        /// bt_events 走 ringbuf 上报断连事件。前者是 legacy 音频能力，
        /// 后者是工业无线诊断的主线。
        ConfigString events_bpf_obj{"build/bt_events.bpf.o"};

        /// Phase 1 HCI ACL 工业数据通道流量探针对象（bt_hci_traffic.bpf.o）
        ConfigString hci_traffic_bpf_obj{"build/bt_hci_traffic.bpf.o"};

        // ---------- Phase 2: 工业蓝牙数据通道异常检测规则阈值 ----------
        std::atomic<uint32_t> stall_timeout_ms{5000};          ///< 业务心跳预期周期（0 表示禁用停顿检测）
        std::atomic<uint32_t> stall_consecutive_windows{2};     ///< 触发停顿的连续超时窗口数
        std::atomic<uint32_t> min_expected_bps{0};              ///< 业务保底吞吐量（0 表示未设定预期）
        std::atomic<uint32_t> degraded_consecutive_windows{3};  ///< 触发劣化的连续窗口数

        // ---------- Phase 3a: 区域关联阈值（SiteIncident）----------
        //
        // 这五个值决定 SiteIncidentCorrelator 的**构造期**配置：插件 start 时
        // 读入一次，运行时 set 后需 `weaknet-cli monitor restart bt_events`
        // 重建关联器才生效（重启回放会恢复既有事故，不丢状态）。
        // 因此它们刻意**不进** isTrialableKey 白名单——与 map_sizing 同理：
        // TRIAL 的"试改成功但无法回滚生效"会给出假象。
        //
        // 受影响设备**最少台数**（双门槛之绝对数；语义下限 2：单台设备坏了
        // 不是区域事故，产品分界线就在这里）
        std::atomic<uint32_t> incident_min_devices{2};
        // 受影响比例门槛（万分比 bp，3000 = 30.00%；双门槛之比例）
        std::atomic<uint32_t> incident_min_ratio_bp{3000};
        // 关联窗口（毫秒）：窗口内累计的合格异常参与同一 incident 判定
        std::atomic<uint32_t> incident_window_ms{60000};
        // 静默窗口（毫秒）：窗口内无新合格异常 → RESOLVED
        std::atomic<uint32_t> incident_quiet_window_ms{60000};
        // 活跃设备记忆（毫秒）：动态分母只统计这段时间内被观测到的设备
        std::atomic<uint32_t> incident_active_window_ms{60000};
    } bluetooth;

    // ---------- eBPF 监控线程 ----------
    struct {
        std::atomic<bool> enabled{true};
        ConfigString bpf_obj{"build/dns_monitor.bpf.o"};
        std::atomic<uint32_t> interval_ms{10000};
        std::atomic<uint32_t> capture_pages{64};             ///< perf ring buffer 页数（每 CPU）
        ConfigString assessment_profile{"INTERNET_ACCESS"};  ///< IR-3: NETWORK_ONLY | INTERNET_ACCESS
        MapSizingCfg map_sizing;                             ///< fd_resolvers/pending_recv/self_endpoints
    } dns;

    struct {
        std::atomic<bool> enabled{true};
        ConfigString bpf_obj{"build/wifi_packet_loss.bpf.o"};
        std::atomic<uint32_t> interval_ms{10000};
    } wifi_loss;

    struct {
        std::atomic<bool> enabled{true};
        ConfigString bpf_obj{"build/http_latency.bpf.o"};
        std::atomic<uint32_t> interval_ms{10000};
        MapSizingCfg map_sizing;   ///< http_txn_stats/recvmsg_ctx_map
    } http_latency;

    struct {
        std::atomic<bool> enabled{true};
        ConfigString bpf_obj{"build/flow_rate.bpf.o"};
        std::atomic<uint32_t> interval_ms{15000};
        MapSizingCfg map_sizing;   ///< current_sec/process_stats（flow_rate 双加载统一归此块）
    } process_profiler;

    struct {
        std::atomic<bool> enabled{true};
        ConfigString bpf_obj{"build/tcp_retransmit.bpf.o"};
        std::atomic<uint32_t> interval_ms{15000};   ///< 原始循环 i<150 × 100ms = 15s
        MapSizingCfg map_sizing;                    ///< retrans_stats/retrans_events
    } tcp_retrans;

    struct {
        std::atomic<bool> enabled{true};
        ConfigString bpf_obj{"build/tcp_conn_stats.bpf.o"};
        std::atomic<uint32_t> interval_ms{15000};   ///< 原始循环 i<150 × 100ms = 15s
        MapSizingCfg map_sizing;                    ///< conn_start/conn_ports
    } tcp_conn;

    struct {
        std::atomic<bool> enabled{true};
        ConfigString bpf_obj{"build/skb_drop.bpf.o"};
        std::atomic<uint32_t> interval_ms{10000};
        MapSizingCfg map_sizing;   ///< drop_stats_map
    } skb_drop;

    struct {
        std::atomic<bool> enabled{true};
        ConfigString bpf_obj{"build/tcp_connect.bpf.o"};
        std::atomic<uint32_t> interval_ms{10000};
        std::atomic<uint32_t> capture_pages{32};
    } tcp_connect;

    struct {
        std::atomic<bool> enabled{true};
        ConfigString bpf_obj{"build/tcp_rtt.bpf.o"};
        std::atomic<uint32_t> interval_ms{10000};
        MapSizingCfg map_sizing;   ///< tcp_rtt_stats
    } tcp_rtt;

    // ---------- 受控主动连通性探测 ----------
    //
    // 默认 **关闭**，且**不内置任何第三方默认目标**。
    // 理由：probe 目标决定了"设备主动连接谁"，也决定了评价体系把谁当作
    // ground truth。硬编码第三方公共服务会产生新的错误 oracle
    // （对方限流/地区不可达/改响应都会被解释成 Internet 故障）。
    // 因此默认 targets 为空；部署方须显式提供 targets 才启用。
    //
    // targets 格式：逗号分隔的 "id|hostname|port"（端口可省略，默认 443）。
    // 本项目 YAML 解析器只支持 key: value 两级结构，不支持列表语法，
    // 故用逗号分隔字符串表达多目标；至少需要 2 个目标才有判定资格。
    struct {
        std::atomic<bool> enabled{false};
        // 与其它监控器一致，内部统一以**毫秒**存储（setDurationField 的语义）。
        // 此前字段名为 interval_sec 却存 ms，导致线程按"秒"计算 sleep 时长，
        // 探测实际约 2.8 小时才跑一轮 —— 结论长期停留在首轮快照。
        std::atomic<uint32_t> interval_ms{30000};
        std::atomic<uint32_t> timeout_ms{3000};
        ConfigString targets{""};        ///< "id|host|port,id|host|port"
        // HTTPS 探测开关。关闭时 evaluator 返回 NO_CAPABILITY
        // （reason=no_tls_probe_capability），绝不因 DNS/TCP 成功就宣称 HTTPS 可用。
        std::atomic<bool> https_enabled{true};
        // Portal oracle 开关。开启后额外做一次**明文 HTTP** connectivity-check
        // 请求，比对是否被重定向/替换内容。
        std::atomic<bool> portal_check_enabled{false};
        // Portal oracle 的受控端点。格式同 targets（"id|host|port"），
        // 但语义不同：这些端点必须是**响应已知**的 connectivity-check 服务。
        // 默认空 → 不做 oracle 探测 → Portal 返回 NO_CAPABILITY，
        // 绝不退回"观测到 302 就算门户"这种推测。
        ConfigString portal_targets{""};
        // 明文 HTTP 路径（Portal oracle 用），默认 "/"
        ConfigString portal_path{"/"};
        // oracle 响应正文必须包含的子串；空则不比对正文
        ConfigString portal_expect_body{""};
    } active_probe;

    // ---------- 边缘遥测上报（WeakNet → 中心平台）----------
    //
    // 默认 **关闭**，且**不内置任何默认服务端地址**。理由与 active_probe
    // 的 targets 相同：上报会把"这台设备主动把网络状态发给谁"变成系统事实，
    // 硬编码一个默认 endpoint 会让每个部署都默认向第三方外发数据。
    //
    // 启用时必须同时提供 url / device_id / token / private_key_path，
    // 缺一不可（否则 exporter 记 error 并保持关闭，不会半启用）。
    //
    // 安全语义：请求体是签名覆盖的原始字节，签名走 Ed25519（OpenSSL）。
    // 服务端用同一份字节验签，因此本端**不得**在签名后重新序列化。
    struct {
        std::atomic<bool> enabled{false};
        // 形如 "http://host:8000/api/v1/network/edge/telemetry"
        ConfigString url{""};
        // 租户标识，作为 X-Edge-Tenant 头；服务端据此归属数据
        ConfigString tenant{""};
        // 设备唯一标识（同时是服务端资产主键），字符集 [A-Za-z0-9._-]
        ConfigString device_id{""};
        // 现场标识（site_id）：多网关部署时**同一现场的多台网关共享此值**，
        // 云端据此把多探针观测聚合成一个现场视图。
        //
        // 留空则回落 device_id —— 即 Phase 1/3a 的 "1 Gateway = 1 Site"
        // 行为完全不变，单网关部署无需配置此项。
        ConfigString site_id{""};
        // 设备预共享令牌，作为 X-Edge-Token 头（非机密中的机密，仍是凭据）
        ConfigString token{""};
        // Ed25519 私钥 PEM 路径；与 token 一起决定上报身份
        ConfigString private_key_path{""};
        // 密钥标识（服务端据 X-Edge-Key-Id 选择信任锚）
        ConfigString key_id{""};
        // 云端下行验签公钥（Ed25519 PEM）：非空时，telemetry 响应里的
        // pending_actions 必须携带对该数组字节的有效 detached 签名，
        // 否则整批拒绝（S1）。留空 = 不验签（兼容旧云端，迁移期默认）。
        ConfigString cloud_public_key_path{""};
        // 允许非回环明文 HTTP 上报（仅实验环境）。默认 false：
        // edge.url 指向非回环地址且 scheme 为 http 时拒绝加载，
        // 防止令牌/签名密钥在链路上裸奔（S1#3）。
        std::atomic<bool> allow_insecure_http{false};
        // 上报周期；与评估节奏（quality 线程）对齐，一个周期最多一条
        std::atomic<uint32_t> interval_ms{10000};
        // 单次 HTTP 请求超时；弱网下不宜过长，失败留待下一轮补发
        std::atomic<uint32_t> timeout_ms{5000};
    } edge;
};

/**
 * @brief 加载 YAML 子集配置文件并填充 WeakNetConfig
 *
 * 支持语法（两段缩进、注释、时长后缀），见实现注释。缺字段回落默认值，
 * 语法/未知键错误返回 false 并带行号。
 *
 * @param path   配置文件路径；不存在时返回 true 且 out 保持默认值
 * @param out    输出配置（不存在的键保留既有值）
 * @param error  失败时填充错误描述（含行号）
 * @return true 成功（或文件不存在）；false 语法错误
 */
bool loadWeakNetConfig(const std::string& path, WeakNetConfig* out, std::string* error);

/// 读取或更新指定监控器的 enabled 开关（供生命周期管理器同步运行意图）。

