namespace weaknet_dbus {

class ServerContext;

/// 监控器插件生命周期接口
class IMonitorPlugin {
public:
    virtual ~IMonitorPlugin() = default;

    /// 插件唯一名（如 "rtt"、"dns"）；用于日志与注册表去重
    virtual const char* name() const = 0;

    /// 启动优先级：小者先启动（start 正序、stop 逆序）；默认 100
    virtual int order() const { return 100; }

    /// 返回本插件依赖的其他插件名称；默认无依赖。
    virtual std::vector<std::string> dependencies() const { return {}; }

    /// 阶段1：加载资源、解析配置；失败时 start 不得执行。
    virtual bool init(ServerContext* ctx) = 0;

    /// 阶段2：启动线程（内部应做 enabled 守卫）。
    /// @return true 成功；false 失败（不影响其他插件启动）
    virtual bool start(ServerContext* ctx) = 0;

    /// 阶段3：停止线程、释放插件自身持有的资源。
    /// 由 server.cpp 在 join 全部线程后、~ServerContext 前按 order() 逆序调用。
    /// 当前各插件实现为空（资源由 ctx 的 unique_ptr 统一回收），预留给未来自管资源的插件使用。
    virtual void stop() = 0;
};

}  // namespace weaknet_dbus=== registry cpp ===
/**
 * @file monitor_registry.cpp
 * @brief 监控器插件静态注册表实现
 *
 * 内部用函数级静态变量持有注册表（构造时注册，跨编译单元安全）。
 * instantiateAllPlugins 按 order() 升序返回。
 * 停止时由 server.cpp 在 join 全部线程后按 order() 逆序显式调用 stop()；
 * 插件 vector 析构顺序为反向构造顺序，不保证与 order() 逆序一致。
 */

#include "monitor_registry.hpp"

#include <algorithm>
#include <map>
#include <mutex>

#include "logger.hpp"

namespace weaknet_dbus {

namespace {

struct Registry {
    std::map<std::string, PluginFactory> factories;  ///< 名字 → 工厂（map 保序，去重）
    std::mutex mutex;
};

Registry& registry() {
    static Registry r;
    return r;
}

}  // namespace

void registerPlugin(const char* name, PluginFactory factory) {
    if (!name || !factory) return;
    auto& r = registry();
    std::lock_guard<std::mutex> lock(r.mutex);
    if (r.factories.find(name) != r.factories.end()) {
        LOG_WARNING(LogModule::SYSTEM, "monitor registry: duplicate plugin name '" << name
                    << "' ignored");
        return;
    }
    r.factories.emplace(name, std::move(factory));
}

std::vector<std::unique_ptr<IMonitorPlugin>> instantiateAllPlugins() {
    auto& r = registry();
    std::lock_guard<std::mutex> lock(r.mutex);

    std::vector<std::unique_ptr<IMonitorPlugin>> plugins;
    plugins.reserve(r.factories.size());
    for (auto& [name, factory] : r.factories) {
        auto plugin = factory();
        if (plugin) {
            plugin->name();  // 触发虚调用，确保动态类型完整
            plugins.push_back(std::move(plugin));
        }
    }

    // 按 order() 升序（依赖在前）
    std::stable_sort(plugins.begin(), plugins.end(),
                     [](const std::unique_ptr<IMonitorPlugin>& a,
                        const std::unique_ptr<IMonitorPlugin>& b) {
                         return a->order() < b->order();
                     });
    return plugins;
}

}  // namespace weaknet_dbus

