cd /home/ubuntu/个人学习/AI-powered-Network-Diagnostics
python3 - <<'EOF'
import re,os,subprocess
hdrs=[]
for root,dirs,files in os.walk('server/include'):
    for f in files:
        if f.endswith(('.hpp','.h')): hdrs.append(os.path.join(root,f))
decl=set()
for h in hdrs:
    txt=open(h,encoding='utf-8',errors='replace').read()
    for m in re.finditer(r'(?m)^[ \t]*(?:static\s+|virtual\s+|inline\s+|explicit\s+|const\s+)*[\w:<>&*\s]+?[\s*&]\s*(\w+)\s*\([^;{]*\)\s*(?:const)?\s*(?:override)?\s*(?:noexcept)?\s*[;{]', txt):
        n=m.group(1)
        if n in ('if','for','while','switch','return','sizeof','catch','namespace'): continue
        decl.add(n)
out=[]
for n in sorted(decl):
    if len(n)<5: continue
    r=subprocess.run(['rg','-c','-w',n,'server/src','client','server/include','server/CMakeLists.txt'],capture_output=True,text=True)
    tot=0
    for line in r.stdout.strip().split('\n'):
        if not line: continue
        try: tot+=int(line.rsplit(':',1)[1])
        except: pass
    if tot<=2:
        out.append((tot,n))
print(len(out))
for t,n in sorted(out): print(t,n)
EOF

